CREATE TABLE "StudioOrganization" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "brand" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO "StudioOrganization" ("id","name","brand") VALUES ('studiojeker','Studiojeker GmbH','{"logo":"studiojeker-original.svg","colors":{"black":"#000000","white":"#ffffff","cyan":"#00c8ff"},"fontAssetId":null,"tone":"Schweizer Hochdeutsch, persönlich, professionell","templatesVersion":"studio-v1"}');
ALTER TABLE "Contact" ADD COLUMN "organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id");
ALTER TABLE "Draft" ADD COLUMN "organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id");
ALTER TABLE "Campaign" ADD COLUMN "organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id");
ALTER TABLE "MarketingContent" ADD COLUMN "organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id");
CREATE TABLE "StudioSeries" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id"), "title" TEXT NOT NULL,"briefing" JSONB NOT NULL,"ownerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "MarketingContent" ADD COLUMN "studioSeriesId" TEXT REFERENCES "StudioSeries"("id");
CREATE TABLE "StudioAsset" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id"),"objectKey" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"mime" TEXT NOT NULL,"size" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"kind" TEXT NOT NULL,"width" INTEGER,"height" INTEGER,"userId" TEXT NOT NULL,"deletedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StudioAsset_organizationId_createdAt_idx" ON "StudioAsset"("organizationId","createdAt");
CREATE TABLE "StudioJob" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL DEFAULT 'studiojeker' REFERENCES "StudioOrganization"("id"),"seriesId" TEXT NOT NULL REFERENCES "StudioSeries"("id"),"requestKey" TEXT NOT NULL UNIQUE,"kind" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"input" JSONB NOT NULL,"result" JSONB,"model" TEXT NOT NULL,"reserveUsd" DOUBLE PRECISION NOT NULL,"usage" JSONB,"error" TEXT,"providerRequestId" TEXT,"userId" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "StudioJob_organizationId_status_createdAt_idx" ON "StudioJob"("organizationId","status","createdAt");
